#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

# This wizard has no CI and no .env convention (topro is a static site — config
# lives in a plain JS file the browser loads). We use ENV_FILE purely as a
# scratch capture file so re-runs remember values already entered; the real
# deliverable is js/firebase-config.js, written in the final stage.
ENV_FILE="${ENV_FILE:-.firebase-setup.env}"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
CONFIG_FILE="$REPO_ROOT/js/firebase-config.js"

banner "TO PRO — Firebase project setup"

# ── Stage 1: create the project ────────────────────────────────────────────
stage "Create the Firebase project"
say "Everything for the swim-camp admin system (database, login, image storage)"
say "lives in one Firebase project. If you already made one for this, just open it."
open_url "https://console.firebase.google.com/"
step "Click 'Add project' (or open your existing TO PRO project if you already made one)."
step "Name it something like 'topro-admin' and finish the creation wizard (Google"
step "Analytics is not needed — you can turn it off)."
pause "Project created and open in the console?"

# ── Stage 2: Firestore ─────────────────────────────────────────────────────
stage "Enable Cloud Firestore"
say "This is the database that stores your pages and registration submissions."
say "Firebase's console nav has been reorganized a few times — if the sidebar"
say "labels below don't match what you see, use the search box at the very top"
say "of the left sidebar ('搜尋產品' / 'Search products') and type 'Firestore'"
say "instead — that's the most reliable way to find it regardless of layout."
step "Left sidebar: '資料庫和儲存空間' (Database and Storage) → Firestore →"
step "Create database."
step "Choose 'Start in production mode' (we deploy real security rules in a"
step "later stage, so this is safe)."
step "Pick a location close to Taiwan, e.g. 'asia-east1 (Taiwan)', then Enable."
pause "Firestore database created?"

# ── Stage 3: Authentication ────────────────────────────────────────────────
stage "Enable Authentication (Email/Password)"
say "This is how you'll log into the admin screen."
say "Same note as last stage: if you don't see 'Authentication' where this"
say "says, use the sidebar search box and type 'Authentication'."
step "Left sidebar: '安全性' (Security) → Authentication → Get started."
step "Under 'Sign-in method', click 'Email/Password', toggle it Enabled, Save."
pause "Email/Password sign-in enabled?"

# ── Stage 4: Storage (optional) ────────────────────────────────────────────
stage "Enable Storage (optional)"
say "This is where uploaded images (course photos etc.) would live — but"
say "Firebase now requires upgrading the project to the pay-as-you-go 'Blaze'"
say "plan (needs a credit card on file) before Storage can be enabled at all,"
say "even though real usage will stay \$0 within the free quota."
say "This is entirely optional: the admin's image blocks also accept a plain"
say "image URL (upload anywhere free — Google Drive, Imgur, etc. — and paste"
say "the link in). Skip this stage unless you specifically want in-admin file"
say "uploads and are OK adding a card."
STORAGE_ENABLED=0
if confirm "Skip Storage for now (you can enable it later, nothing else depends on it)?"; then
  note "Skipped — use 'paste image URL' in the admin's image blocks instead."
else
  STORAGE_ENABLED=1
  step "Left sidebar: '資料庫和儲存空間' (Database and Storage) → Storage (under"
  step "'物件儲存空間' / Object storage) → Get started. It will prompt you to"
  step "upgrade to Blaze first — follow that flow, then come back here."
  step "Accept the default (production) rules for now — we replace them with our"
  step "own rules in Stage 7 — then pick the same region as Firestore and Done."
  pause "Storage bucket created?"
fi

# ── Stage 5: register a web app, capture config ────────────────────────────
stage "Register a Web App"
say "This gives us the config object the site's JS needs to talk to Firebase."
step "Click the gear icon (top left, next to 'Project Overview') → Project settings."
step "Scroll to 'Your apps' → click the </> (Web) icon."
step "Name it 'topro-site' (Firebase Hosting is NOT needed — leave that unchecked),"
step "then Register app."
step "You'll see a firebaseConfig object like:"
note "  const firebaseConfig = { apiKey: \"...\", authDomain: \"...\", projectId: \"...\","
note "    storageBucket: \"...\", messagingSenderId: \"...\", appId: \"...\" };"
say "Copy each value below (paste just the value, no quotes needed)."
ask FIREBASE_API_KEY "apiKey:"
ask FIREBASE_AUTH_DOMAIN "authDomain:"
ask FIREBASE_PROJECT_ID "projectId:"
ask FIREBASE_STORAGE_BUCKET "storageBucket:"
ask FIREBASE_MESSAGING_SENDER_ID "messagingSenderId:"
ask FIREBASE_APP_ID "appId:"
write_env FIREBASE_API_KEY "$FIREBASE_API_KEY"
write_env FIREBASE_AUTH_DOMAIN "$FIREBASE_AUTH_DOMAIN"
write_env FIREBASE_PROJECT_ID "$FIREBASE_PROJECT_ID"
write_env FIREBASE_STORAGE_BUCKET "$FIREBASE_STORAGE_BUCKET"
write_env FIREBASE_MESSAGING_SENDER_ID "$FIREBASE_MESSAGING_SENDER_ID"
write_env FIREBASE_APP_ID "$FIREBASE_APP_ID"

# ── Stage 6: Firestore rules ───────────────────────────────────────────────
stage "Deploy Firestore Security Rules"
say "These rules make sure only you (the admin) can write pages, visitors can"
say "only read published pages, and nobody can read other people's sign-ups."
open_url "https://console.firebase.google.com/project/_/firestore/rules"
step "Select your project if prompted."
step "Delete everything in the rules editor and paste this in full:"
note '  rules_version = '"'"'2'"'"';'
note '  service cloud.firestore {'
note '    match /databases/{database}/documents {'
note '      function isAdmin() {'
note '        return request.auth != null &&'
note '          exists(/databases/$(database)/documents/admins/$(request.auth.uid));'
note '      }'
note '      match /pages/{slug} {'
note '        allow read: if resource.data.status == '"'"'published'"'"' || isAdmin();'
note '        allow create, update, delete: if isAdmin();'
note '      }'
note '      match /submissions/{submissionId} {'
note '        allow create: if'
note '          request.resource.data.keys().hasAll(['"'"'pageSlug'"'"','"'"'formId'"'"','"'"'data'"'"','"'"'submittedAt'"'"']) &&'
note '          request.resource.data.pageSlug is string &&'
note '          request.resource.data.submittedAt == request.time;'
note '        allow read, list, update, delete: if isAdmin();'
note '      }'
note '      match /admins/{uid} {'
note '        allow read: if isAdmin();'
note '        allow write: if isAdmin();'
note '      }'
note '      match /schedule_items/{id} {'
note '        allow read: if true;'
note '        allow write: if isAdmin();'
note '      }'
note '      match /carousel_slides/{id} {'
note '        allow read: if true;'
note '        allow write: if isAdmin();'
note '      }'
note '      match /course_cards/{id} {'
note '        allow read: if true;'
note '        allow write: if isAdmin();'
note '      }'
note '      match /site_settings/{id}   { allow read, write: if false; }'
note '    }'
note '  }'
step "Click Publish."
pause "Firestore rules published?"

# ── Stage 7: Storage rules (only if Storage was enabled in Stage 4) ────────
stage "Deploy Storage Security Rules"
if [[ "$STORAGE_ENABLED" != "1" ]]; then
  note "Skipped — you skipped Storage in Stage 4, nothing to deploy rules for."
  note "Come back and re-run this script if you enable Storage later."
else
  say "Same idea, for uploaded images: public can view, only the admin can upload."
  open_url "https://console.firebase.google.com/project/_/storage/_/rules"
  step "Paste this in full, replacing what's there:"
  note '  rules_version = '"'"'2'"'"';'
  note '  service firebase.storage {'
  note '    match /b/{bucket}/o {'
  note '      match /pages/{slug}/{allPaths=**} {'
  note '        allow read: if true;'
  note '        allow write: if request.auth != null &&'
  note '          firestore.exists(/databases/(default)/documents/admins/$(request.auth.uid));'
  note '      }'
  note '    }'
  note '  }'
  warn "If Publish fails with an error mentioning 'firestore.exists' or"
  warn "cross-service rules not supported, use this simpler version instead (any"
  warn "logged-in user can upload — fine for now since only you can log in):"
  note '  rules_version = '"'"'2'"'"';'
  note '  service firebase.storage {'
  note '    match /b/{bucket}/o {'
  note '      match /pages/{slug}/{allPaths=**} {'
  note '        allow read: if true;'
  note '        allow write: if request.auth != null;'
  note '      }'
  note '    }'
  note '  }'
  step "Click Publish."
  pause "Storage rules published?"
fi

# ── Stage 8: admin user + admins/{uid} doc ─────────────────────────────────
stage "Create your admin login"
say "Last step — create the one login you'll use for the admin screen, and"
say "tell Firestore that uid is allowed to write things (this is what the"
say "isAdmin() check in the rules above looks up)."
open_url "https://console.firebase.google.com/project/_/authentication/users"
step "Click 'Add user'. Enter the email + password you want to log in with."
step "After it's created, click into that user row and copy their 'User UID'"
step "(a long string like 'aB3xY...')."
ask FIREBASE_ADMIN_EMAIL "Admin email you just created:"
ask FIREBASE_ADMIN_UID "That user's UID:"
write_env FIREBASE_ADMIN_EMAIL "$FIREBASE_ADMIN_EMAIL"
write_env FIREBASE_ADMIN_UID "$FIREBASE_ADMIN_UID"
say ""
say "Now create the matching document so the rules recognize this account:"
open_url "https://console.firebase.google.com/project/_/firestore/data"
step "Click 'Start collection'. Collection ID: admins"
step "Document ID: paste the UID you just copied (NOT auto-ID — must be the UID)."
step "Add field 'email' (type: string) → paste the admin email."
step "Add field 'addedAt' (type: timestamp) → click the clock icon to use 'now'."
step "Save."
pause "admins/{uid} document created?"

# ── Write the real deliverable: js/firebase-config.js ──────────────────────
mkdir -p "$(dirname "$CONFIG_FILE")"
cat > "$CONFIG_FILE" <<EOF
// Generated by scripts/setup-firebase.sh — shared Firebase init for both the
// public site (event-page.html) and the admin app (admin.html).
// Safe to commit: these are public client identifiers, not secrets — access
// control is enforced by the Firestore/Storage security rules, not by hiding
// this file. Re-run scripts/setup-firebase.sh if you ever need to point this
// at a different Firebase project.
import { initializeApp } from "https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js";
import { getFirestore } from "https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js";
import { getAuth } from "https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js";
import { getStorage } from "https://www.gstatic.com/firebasejs/10.14.1/firebase-storage.js";

const firebaseConfig = {
  apiKey: "$FIREBASE_API_KEY",
  authDomain: "$FIREBASE_AUTH_DOMAIN",
  projectId: "$FIREBASE_PROJECT_ID",
  storageBucket: "$FIREBASE_STORAGE_BUCKET",
  messagingSenderId: "$FIREBASE_MESSAGING_SENDER_ID",
  appId: "$FIREBASE_APP_ID",
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);
export const auth = getAuth(app);
export const storage = getStorage(app);
EOF
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$CONFIG_FILE"
note "  Admin login: $FIREBASE_ADMIN_EMAIL (uid $FIREBASE_ADMIN_UID) — keep the"
note "  password somewhere safe, this script never stores it."

finish
